style.css:
:root {
    --red: #e50914;
    --red-dark: #8b0a12;
    --wine: #2b0d12;
    --black: #090708;
    --dark: #11090b;
    --text: #f5f5f5;
    --subtext: #a99da0;
}

html,
body {
    background-color: var(--black) !important;
}

body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -1;
    background-image: url("https://w0.peakpx.com/wallpaper/127/11/HD-wallpaper-music-singer-the-weeknd-thumbnail.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
}

body {
    --background-base: var(--black) !important;
    --background-highlight: var(--wine) !important;
    --background-press: #421018 !important;
    --background-elevated-base: #170b0e !important;
    --background-elevated-highlight: #2a1015 !important;
    --background-elevated-press: #3a0d14 !important;
    --background-tinted-base: var(--dark) !important;
    --background-tinted-highlight: var(--wine) !important;
    --text-base: var(--text) !important;
    --text-subdued: var(--subtext) !important;
    --text-bright-accent: var(--red) !important;
    --essential-base: var(--red) !important;
    --essential-subdued: var(--red-dark) !important;
    --decorative-base: var(--red) !important;
    --decorative-subdued: var(--red-dark) !important;
}

main {
    background-color: rgba(9, 7, 8, 0.72) !important;
}

aside {
    background-color: rgba(9, 7, 8, 0.94) !important;
}

footer {
    background-color: rgba(17, 9, 11, 0.96) !important;
    border-top: 1px solid var(--red-dark) !important;
}

button:hover {
    color: var(--red) !important;
}

a:hover {
    color: var(--red) !important;
}

input[type="range"] {
    accent-color: var(--red) !important;
}

[aria-current="page"] {
    color: var(--red) !important;
}

[aria-selected="true"] {
    color: var(--red) !important;
}

[role="menu"],
[role="dialog"],
[role="listbox"] {
    background-color: var(--dark) !important;
    border-color: var(--red-dark) !important;
}

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: var(--black) !important;
}

::-webkit-scrollbar-thumb {
    background: var(--red-dark) !important;
}

::-webkit-scrollbar-thumb:hover {
    background: var(--red) !important;
}
